import React, { useState, useEffect } from "react";
import { useNavigate, useSearchParams } from "react-router-dom";

const API_URL = "http://localhost:5000/api";

function Gallery() {
  const [products, setProducts] = useState([]);
  const [categories, setCategories] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  
  // Local state for the search input so it types smoothly
  const [searchTyped, setSearchTyped] = useState("");

  const navigate = useNavigate();
  const [searchParams, setSearchParams] = useSearchParams();

  // Get current filters from the URL
  const selectedCategory = searchParams.get("category") || "";
  const searchQuery = searchParams.get("search") || "";
  const sortBy = searchParams.get("sort") || "default";

  // 1. Sync the search box with the URL when the page first loads
  useEffect(() => {
    setSearchTyped(searchQuery);
    fetch(API_URL + "/categories")
      .then((res) => res.json())
      .then((data) => setCategories(data))
      .catch((err) => console.log("Category error", err));
  }, []);

  // 2. Fetch Products whenever search or category in URL changes
  useEffect(() => {
    setLoading(true);
    let url = API_URL + "/products?";
    if (searchQuery) url += "search=" + encodeURIComponent(searchQuery) + "&";
    if (selectedCategory) url += "category=" + selectedCategory;

    fetch(url)
      .then((res) => {
        if (!res.ok) throw new Error("Failed to load products");
        return res.json();
      })
      .then((data) => {
        setProducts(data);
        setLoading(false);
      })
      .catch((err) => {
        setError(err.message);
        setLoading(false);
      });
  }, [searchQuery, selectedCategory]);

  // 3. Update URL function (Prevents hover from clearing the URL)
  const updateUrl = (key, value) => {
    // We create a new URLSearchParams object based on the CURRENT one
    const newParams = new URLSearchParams(searchParams);
    if (value) {
      newParams.set(key, value);
    } else {
      newParams.delete(key);
    }
    setSearchParams(newParams, { replace: true });
  };

  // 4. Simple sorting
  const getSortedProducts = () => {
    let list = [...products];
    if (sortBy === "price-asc") list.sort((a, b) => a.price - b.price);
    if (sortBy === "price-desc") list.sort((a, b) => b.price - a.price);
    if (sortBy === "name") list.sort((a, b) => a.name.localeCompare(b.name));
    return list;
  };

  const finalProducts = getSortedProducts();

  return (
    <div className="container py-5">
      <div className="row">
        
        {/* Sidebar */}
        <div className="col-md-3">
          <h5 className="mb-4">Filters</h5>
          
          <div className="mb-4">
            <label className="fw-bold small mb-2">SEARCH</label>
            <div className="d-flex gap-2">
              <input
                type="text"
                className="form-control"
                placeholder="Search..."
                value={searchTyped}
                onChange={(e) => setSearchTyped(e.target.value)}
                onKeyDown={(e) => { if (e.key === 'Enter') updateUrl("search", searchTyped) }}
              />
              <button 
                className="btn btn-dark btn-sm"
                onClick={() => updateUrl("search", searchTyped)}
              >
                Go
              </button>
            </div>
          </div>

          <div className="mb-4">
            <label className="fw-bold small mb-2">COLLECTIONS</label>
            <div className="form-check">
              <input 
                className="form-check-input" 
                type="radio" 
                name="cat"
                checked={selectedCategory === ""} 
                onChange={() => updateUrl("category", "")}
              />
              <label className="form-check-label">All</label>
            </div>
            {categories.map((cat) => (
              <div className="form-check" key={cat._id}>
                <input
                  className="form-check-input"
                  type="radio"
                  name="cat"
                  checked={selectedCategory === cat._id}
                  onChange={() => updateUrl("category", cat._id)}
                />
                <label className="form-check-label">{cat.name}</label>
              </div>
            ))}
          </div>
        </div>

        {/* Grid */}
        <div className="col-md-9">
          <div className="d-flex justify-content-between align-items-center mb-4">
            <h4 className="serif">Gallery</h4>
            <select 
              className="form-select w-auto" 
              value={sortBy}
              onChange={(e) => updateUrl("sort", e.target.value)}
            >
              <option value="default">Sort By</option>
              <option value="price-asc">Price: Low to High</option>
              <option value="price-desc">Price: High to Low</option>
              <option value="name">Name A-Z</option>
            </select>
          </div>

          {loading ? (
            <p>Loading frames...</p>
          ) : error ? (
            <div className="alert alert-danger">{error}</div>
          ) : (
            <div className="row g-3">
              {finalProducts.map((p) => (
                <div className="col-md-4" key={p._id}>
                  <div 
                    className="card h-100 border-0 shadow-sm" 
                    style={{ cursor: "pointer" }}
                    onClick={() => navigate("/product/" + p._id)}
                  >
                    <img 
                      src={p.image} 
                      className="card-img-top" 
                      alt={p.name} 
                      style={{ height: "240px", objectFit: "cover" }}
                    />
                    <div className="card-body px-2">
                      <h6 className="mb-1">{p.name}</h6>
                      <p className="text-muted small">{p.price} EGP</p>
                    </div>
                  </div>
                </div>
              ))}
              {finalProducts.length === 0 && <p className="text-center mt-5">No frames match your search.</p>}
            </div>
          )}
        </div>

      </div>
    </div>
  );
}

export default Gallery;
